"use client";
/* Scout, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Scout(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("scout"); }, []);
  return React.createElement("piix-pal", { "pal": "scout", ...piixAttrs(props) });
}

export default Scout;
